    @GwtIncompatible("Builder impl")
    public void testBuilderForceCopy() {
      ImmutableList.Builder<Integer> builder = ImmutableList.builder();
      Object[] prevArray = null;
      for (int i = 0; i < 10; i++) {
        builder.add(i);
