    assertThat(Throwables.getCauseAs(thrown, SomeCheckedException.class)).isSameInstanceAs(cause);
    assertThat(Throwables.getCauseAs(thrown, Exception.class)).isSameInstanceAs(cause);

    ClassCastException expected =
