          List<String> expected = sample.subList(0, i);
          misleading.addAll(expected);
          assertEquals(expected, ImmutableList.copyOf(misleading));
          assertEquals(expected, ImmutableList.copyOf((Iterable<String>) misleading));
        }
      }
    }

